package com.bananalab.lite;
import java.util.*;import org.json.*;
/** Full-sequence reverse-mode differentiation of Banana's own causal Transformer. */
final class TransformerTraining{
 static final class Tensor{final float[][] v,g;Tensor(float[][] v){this.v=v;g=new float[v.length][v[0].length];}Tensor(int n,int d){this(new float[n][d]);}}
 static final class Tape{
 final List<Runnable> back=new ArrayList<>();final List<Tensor> params=new ArrayList<>();
 Tensor param(float[][] v){Tensor t=new Tensor(v);params.add(t);return t;}Tensor param(float[] v){return param(new float[][]{v});}
 Tensor add(final Tensor a,final Tensor b){final Tensor y=new Tensor(a.v.length,a.v[0].length);for(int t=0;t<y.v.length;t++)for(int j=0;j<y.v[t].length;j++)y.v[t][j]=a.v[t][j]+b.v[t][j];back.add(new Runnable(){public void run(){for(int t=0;t<y.v.length;t++)for(int j=0;j<y.v[t].length;j++){a.g[t][j]+=y.g[t][j];b.g[t][j]+=y.g[t][j];}}});return y;}
 Tensor embed(final int[] tokens,final Tensor e,final Tensor p){final Tensor y=new Tensor(tokens.length,e.v[0].length);for(int t=0;t<tokens.length;t++)for(int j=0;j<y.v[t].length;j++)y.v[t][j]=e.v[tokens[t]][j]+p.v[t][j];back.add(new Runnable(){public void run(){for(int t=0;t<tokens.length;t++)for(int j=0;j<y.v[t].length;j++){e.g[tokens[t]][j]+=y.g[t][j];p.g[t][j]+=y.g[t][j];}}});return y;}
 Tensor linear(final Tensor x,final Tensor w,final Tensor b){final Tensor y=new Tensor(x.v.length,b.v[0].length);for(int t=0;t<y.v.length;t++){System.arraycopy(b.v[0],0,y.v[t],0,y.v[t].length);for(int i=0;i<w.v.length;i++)for(int j=0;j<y.v[t].length;j++)y.v[t][j]+=x.v[t][i]*w.v[i][j];}back.add(new Runnable(){public void run(){for(int t=0;t<y.v.length;t++){for(int j=0;j<y.v[t].length;j++)b.g[0][j]+=y.g[t][j];for(int i=0;i<w.v.length;i++)for(int j=0;j<y.v[t].length;j++){x.g[t][i]+=y.g[t][j]*w.v[i][j];w.g[i][j]+=x.v[t][i]*y.g[t][j];}}}});return y;}
 Tensor norm(final Tensor x,final Tensor w,final Tensor b){final int d=x.v[0].length;final Tensor y=new Tensor(x.v.length,d);final float[][] z=new float[x.v.length][d];final float[] inv=new float[x.v.length];for(int t=0;t<x.v.length;t++){float mean=0,var=0;for(float v:x.v[t])mean+=v;mean/=d;for(float v:x.v[t])var+=(v-mean)*(v-mean);inv[t]=1f/(float)Math.sqrt(var/d+1e-5f);for(int j=0;j<d;j++){z[t][j]=(x.v[t][j]-mean)*inv[t];y.v[t][j]=z[t][j]*w.v[0][j]+b.v[0][j];}}back.add(new Runnable(){public void run(){for(int t=0;t<x.v.length;t++){float sum=0,product=0;for(int j=0;j<d;j++){float g=y.g[t][j]*w.v[0][j];sum+=g;product+=g*z[t][j];w.g[0][j]+=y.g[t][j]*z[t][j];b.g[0][j]+=y.g[t][j];}for(int j=0;j<d;j++)x.g[t][j]+=inv[t]*(y.g[t][j]*w.v[0][j]-sum/d-z[t][j]*product/d);}}});return y;}
 /** Rows from..end of x, so the output layer is only computed where there are labels. */
 Tensor tail(final Tensor x,final int from){final int n=x.v.length-from;final Tensor y=new Tensor(n,x.v[0].length);for(int t=0;t<n;t++)System.arraycopy(x.v[from+t],0,y.v[t],0,y.v[t].length);back.add(new Runnable(){public void run(){for(int t=0;t<n;t++)for(int j=0;j<y.v[t].length;j++)x.g[from+t][j]+=y.g[t][j];}});return y;}
 Tensor relu(final Tensor x){final Tensor y=new Tensor(x.v.length,x.v[0].length);for(int t=0;t<x.v.length;t++)for(int j=0;j<x.v[t].length;j++)y.v[t][j]=Math.max(0,x.v[t][j]);back.add(new Runnable(){public void run(){for(int t=0;t<x.v.length;t++)for(int j=0;j<x.v[t].length;j++)if(x.v[t][j]>0)x.g[t][j]+=y.g[t][j];}});return y;}
 Tensor attention(final Tensor qkv,final int d,final int heads){final int n=qkv.v.length,width=d/heads;final float scale=1f/(float)Math.sqrt(width);final Tensor y=new Tensor(n,d);final float[][][] prob=new float[heads][n][n];for(int h=0;h<heads;h++)for(int t=0;t<n;t++){float max=-Float.MAX_VALUE,total=0;for(int p=0;p<=t;p++){float sum=0;for(int j=0;j<width;j++)sum+=qkv.v[t][h*width+j]*qkv.v[p][d+h*width+j];prob[h][t][p]=sum*scale;max=Math.max(max,sum*scale);}for(int p=0;p<=t;p++){prob[h][t][p]=(float)Math.exp(prob[h][t][p]-max);total+=prob[h][t][p];}for(int p=0;p<=t;p++){prob[h][t][p]/=total;for(int j=0;j<width;j++)y.v[t][h*width+j]+=prob[h][t][p]*qkv.v[p][2*d+h*width+j];}}back.add(new Runnable(){public void run(){for(int h=0;h<heads;h++)for(int t=0;t<n;t++){float[] dp=new float[t+1];float mean=0;for(int p=0;p<=t;p++){for(int j=0;j<width;j++){dp[p]+=y.g[t][h*width+j]*qkv.v[p][2*d+h*width+j];qkv.g[p][2*d+h*width+j]+=prob[h][t][p]*y.g[t][h*width+j];}mean+=prob[h][t][p]*dp[p];}for(int p=0;p<=t;p++){float ds=prob[h][t][p]*(dp[p]-mean)*scale;for(int j=0;j<width;j++){qkv.g[t][h*width+j]+=ds*qkv.v[p][d+h*width+j];qkv.g[p][d+h*width+j]+=ds*qkv.v[t][h*width+j];}}}}});return y;}
 void backward(){for(int i=back.size()-1;i>=0;i--)back.get(i).run();}
 void update(float rate){double norm=0;for(Tensor p:params)for(float[] row:p.g)for(float g:row)norm+=(double)g*g;float scale=norm>1?(float)(1/Math.sqrt(norm)):1;for(Tensor p:params)for(int i=0;i<p.v.length;i++)for(int j=0;j<p.v[i].length;j++)p.v[i][j]-=rate*scale*p.g[i][j];}
 }
 static final class Sequence{final int[] input,labels;Sequence(int[] i,int[] l){input=i;labels=l;}}
 static Sequence sequence(BananaTransformer m,JSONObject row)throws Exception{List<Integer> q=m.encode(row.getString("question"),4096),a=m.encode(row.getString("answer"),4096);if(q.size()>48||a.size()>24)throw new IllegalArgumentException("El entrenamiento completo admite48 tokens de pregunta y24 de respuesta");List<Integer> all=new ArrayList<>();all.add(2);all.add(3);all.addAll(q);all.add(4);int start=all.size()-1;all.addAll(a);int[] input=new int[all.size()],labels=new int[all.size()];Arrays.fill(labels,-1);for(int i=0;i<input.length;i++)input[i]=all.get(i);for(int i=0;i<a.size();i++)labels[start+i]=a.get(i);labels[labels.length-1]=5;return new Sequence(input,labels);}
 static Tensor forward(BananaTransformer m,Tape t,int[] tokens){Tensor x=t.embed(tokens,t.param(m.embedding),t.param(m.position));for(BananaTransformer.Block b:m.blocks){Tensor n=t.norm(x,t.param(b.n1w),t.param(b.n1b));Tensor q=t.linear(n,t.param(b.qkv),t.param(b.qkvb));x=t.add(x,t.linear(t.attention(q,m.d,m.heads),t.param(b.o),t.param(b.ob)));n=t.norm(x,t.param(b.n2w),t.param(b.n2b));x=t.add(x,t.linear(t.relu(t.linear(n,t.param(b.f1),t.param(b.f1b))),t.param(b.f2),t.param(b.f2b)));}return t.linear(t.norm(x,t.param(m.normWeight),t.param(m.normBias)),t.param(m.head),t.param(m.headBias));}
 /** Same network as forward, with the output layer limited to positions from..end. */
 static Tensor forwardTail(BananaTransformer m,Tape t,int[] tokens,int from){Tensor x=t.embed(tokens,t.param(m.embedding),t.param(m.position));for(BananaTransformer.Block b:m.blocks){Tensor n=t.norm(x,t.param(b.n1w),t.param(b.n1b));Tensor q=t.linear(n,t.param(b.qkv),t.param(b.qkvb));x=t.add(x,t.linear(t.attention(q,m.d,m.heads),t.param(b.o),t.param(b.ob)));n=t.norm(x,t.param(b.n2w),t.param(b.n2b));x=t.add(x,t.linear(t.relu(t.linear(n,t.param(b.f1),t.param(b.f1b))),t.param(b.f2),t.param(b.f2b)));}return t.linear(t.norm(t.tail(x,from),t.param(m.normWeight),t.param(m.normBias)),t.param(m.head),t.param(m.headBias));}
 static double loss(Tensor logits,int[] labels,boolean gradient){int count=0;for(int v:labels)if(v>=0)count++;double loss=0;for(int i=0;i<labels.length;i++)if(labels[i]>=0){float[] p=HeadTrainer.probabilities(logits.v[i]);loss-=Math.log(Math.max(1e-12,p[labels[i]]));if(gradient)for(int j=0;j<p.length;j++)logits.g[i][j]=(p[j]-(j==labels[i]?1:0))/count;}return loss/Math.max(1,count);}
 static double evaluate(BananaTransformer m,JSONArray rows)throws Exception{double sum=0;for(int k=0;k<rows.length();k++){Sequence s=sequence(m,rows.getJSONObject(k));BananaTransformer.Session session=m.session();double loss=0;int count=0;for(int i=0;i<s.input.length;i++){float[] p=HeadTrainer.probabilities(session.step(s.input[i]));if(s.labels[i]>=0){loss-=Math.log(Math.max(1e-12,p[s.labels[i]]));count++;}}sum+=loss/Math.max(1,count);}return sum/Math.max(1,rows.length());}
 static List<float[]> parameters(BananaTransformer m){List<float[]> p=new ArrayList<>();rows(p,m.embedding);rows(p,m.position);for(BananaTransformer.Block b:m.blocks){p.add(b.n1w);p.add(b.n1b);rows(p,b.qkv);p.add(b.qkvb);rows(p,b.o);p.add(b.ob);p.add(b.n2w);p.add(b.n2b);rows(p,b.f1);p.add(b.f1b);rows(p,b.f2);p.add(b.f2b);}p.add(m.normWeight);p.add(m.normBias);rows(p,m.head);p.add(m.headBias);return p;}
 static void rows(List<float[]> p,float[][] a){for(float[] row:a)p.add(row);}
 static float[][] snapshot(BananaTransformer m){List<float[]> p=parameters(m);float[][] out=new float[p.size()][];for(int i=0;i<out.length;i++)out[i]=p.get(i).clone();return out;}
 static double distance(BananaTransformer m,float[][] base){List<float[]> p=parameters(m);double n=0;for(int i=0;i<base.length;i++)for(int j=0;j<base[i].length;j++){double d=p.get(i)[j]-base[i][j];n+=d*d;}return Math.sqrt(n);}
 static void project(BananaTransformer m,float[][] base,double radius){double delta=distance(m,base);if(delta>radius){List<float[]> p=parameters(m);float scale=(float)(radius/delta);for(int i=0;i<base.length;i++)for(int j=0;j<base[i].length;j++)p.get(i)[j]=base[i][j]+scale*(p.get(i)[j]-base[i][j]);}}
 static void train(BananaTransformer m,JSONArray train,JSONArray replay)throws Exception{if(train.length()>6||replay.length()>6)throw new IllegalArgumentException("El entrenamiento completo admite hasta6 ejemplos por grupo en Android; no tomé una selección parcial");float[][] base=snapshot(m);for(int epoch=0;epoch<2;epoch++)for(int i=0;i<train.length();i++){if(Thread.currentThread().isInterrupted())throw new IllegalStateException("Entrenamiento cancelado");step(m,sequence(m,train.getJSONObject(i)));if(replay.length()>0)step(m,sequence(m,replay.getJSONObject(i%replay.length())));project(m,base,.01);}}
 static void step(BananaTransformer m,Sequence s){Tape t=new Tape();Tensor out=forward(m,t,s.input);loss(out,s.labels,true);t.backward();t.update(.0002f);}
}
